import pandas as pd

df = pd.DataFrame({
    "listing_id": ["1001", "1002", "1002", "1004"],
    "city": ["Gaza", "Rafah", "Rafah", "gaza "],
    "monthly_rent": [415.0, -20.0, 300.0, None],
})
SCHEMA = {
    "listing_id": {"unique": True},
    "city": {"allowed": ["Gaza", "Rafah"]},
    "monthly_rent": {"min": 50, "max_missing": 0},
}


def validate(df, schema):
    problems = []

    def add(col, message):
        problems.append(f"{col}: {message}")

    for col, rule in schema.items():
        s = df[col]
        if rule.get("unique") and s.duplicated().any():
            add(col, f"{s.duplicated().sum()} repeated value(s)")
        if "allowed" in rule and (~s.isin(rule["allowed"])).any():
            add(col, f"{(~s.isin(rule['allowed'])).sum()} outside the allowed set")
        if "min" in rule and (s < rule["min"]).any():
            add(col, f"{(s < rule['min']).sum()} below {rule['min']}")
        if s.isna().mean() > rule.get("max_missing", 0):
            add(col, f"{s.isna().sum()} missing")
    return problems


problems = validate(df, SCHEMA)
print(len(problems), "problem(s)")
for p in problems:
    print(" -", p)
